    #[test]
    fn retained_data_delete_capabilities_bind_admission_route_and_subject() {
        let tmp = test_util::tempdir();
        let config = test_config(&tmp);
        private_socket_dir(config.socket_path.parent().unwrap());
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let shard_key = test_shard_key(0);
        let payload = b"retained data capability payload";
        let ack = WriteAck {
            stored_size: payload.len() as u64,
            crc64: checksum::crc64::checksum(payload),
        };
        server
            ._node
            .write_shard_file_if_absent(0, &shard_key, payload)
            .unwrap();
        server
            ._node
            .get_pg(0)
            .unwrap()
            .register_written_shards_batch_exact(&[(&shard_key, ack)])
            .unwrap();

        let handler = server.connection_handler();
        let active_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let retained_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let foreign_permit = StorageNodeRouteAdmissionGate::default()
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let payload_request = StorageRpcShardDeleteRequest {
            location: test_location(1, 0, 7).into(),
            shard_key: shard_key.clone(),
        };
        let mismatched_payload_request = StorageRpcShardDeleteRequest {
            location: test_location_with_shard(1, 0, 7, 1).into(),
            shard_key: shard_key.clone(),
        };
        let ack_request = StorageRpcShardAckItemRequest {
            node_id: config.node_id,
            cluster_epoch: config.cluster_epoch,
            pg_id: PgId::new(0),
            shard_key: shard_key.clone(),
        };

        for result in [
            handler.retained_shard_payload_delete_route(
                &active_permit,
                &payload_request,
                "test shard payload delete",
            ),
            handler.retained_shard_payload_delete_route(
                &foreign_permit,
                &payload_request,
                "test shard payload delete",
            ),
        ] {
            match result {
                Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
                Ok(_) => panic!("invalid admission created a retained payload-delete route"),
            }
        }
        let mismatch = match handler.retained_shard_payload_delete_route(
            &retained_permit,
            &mismatched_payload_request,
            "test shard payload delete",
        ) {
            Err(error) => error,
            Ok(_) => panic!("mismatched shard index created a retained payload-delete route"),
        };
        assert_eq!(mismatch.code, StorageRpcErrorCode::PayloadDecode);
        assert_eq!(
            server._node.read_shard_file(0, &shard_key).unwrap(),
            payload
        );

        for result in [
            handler.retained_shard_ack_delete_route(
                &active_permit,
                &ack_request,
                "test shard ack delete",
            ),
            handler.retained_shard_ack_delete_route(
                &foreign_permit,
                &ack_request,
                "test shard ack delete",
            ),
        ] {
            match result {
                Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
                Ok(_) => panic!("invalid admission created a retained ack-delete route"),
            }
        }

        handler
            .retained_shard_payload_delete_route(
                &retained_permit,
                &payload_request,
                "test shard payload delete",
            )
            .unwrap()
            .delete()
            .unwrap();
        handler
            .retained_shard_ack_delete_route(
                &retained_permit,
                &ack_request,
                "test shard ack delete",
            )
            .unwrap()
            .delete()
            .unwrap();
        assert!(matches!(
            server._node.read_shard_file(0, &shard_key),
            Err(StoreError::NotFound)
        ));
        assert!(matches!(
            server._node.get_pg(0).unwrap().stat_shard(&shard_key),
            Err(StoreError::NotFound)
        ));
    }

    #[test]
    fn retained_data_inspection_capabilities_bind_exact_route_primary_and_subject() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.cluster_epoch = ClusterEpoch::new(4).unwrap();
        config.route_map_validity = RouteMapValidity::until_ms(5_000).unwrap();
        config.pg_routes[0].cluster_epoch = config.cluster_epoch;
        config.historical_pg_routes = vec![
            StorageNodePgRoute {
                pg_id: 0,
                cluster_epoch: ClusterEpoch::new(3).unwrap(),
                state: PgState::Active,
                primary_node_id: config.node_id,
                acting_set: vec![config.node_id],
            },
            StorageNodePgRoute {
                pg_id: 0,
                cluster_epoch: ClusterEpoch::new(1).unwrap(),
                state: PgState::Active,
                primary_node_id: NodeId::new(8),
                acting_set: vec![config.node_id, NodeId::new(8)],
            },
        ];
        private_socket_dir(config.socket_path.parent().unwrap());
        let server = crate::clock::with_time_override(1_000, || {
            StorageNodeServer::bind(config.clone()).unwrap()
        });
        let shard_key = test_shard_key(0);
        let payload = b"retained historical data inspection";
        let ack = server
            ._node
            .write_shard_file_if_absent(0, &shard_key, payload)
            .unwrap();
        server
            ._node
            .get_pg(0)
            .unwrap()
            .register_written_shards_batch_exact(&[(&shard_key, ack)])
            .unwrap();

        let handler = server.connection_handler();
        let retained_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let active_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let foreign_permit = StorageNodeRouteAdmissionGate::default()
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let location = test_location(3, 0, config.node_id.as_u32());
        let payload_request = StorageRpcShardReadRequest {
            location: location.into(),
            shard_key: shard_key.clone(),
            expected_ack: ack,
        };
        let ack_request = StorageRpcShardAckItemRequest {
            node_id: config.node_id,
            cluster_epoch: ClusterEpoch::new(3).unwrap(),
            pg_id: PgId::new(0),
            shard_key: shard_key.clone(),
        };

        crate::clock::with_time_override(6_000, || {
            assert_eq!(
                handler
                    .retained_shard_inspection_route(
                        &retained_permit,
                        &payload_request,
                        "test historical shard inspection",
                    )
                    .unwrap()
                    .read()
                    .unwrap(),
                payload
            );
            assert_eq!(
                handler
                    .retained_shard_ack_inspection_route(
                        &retained_permit,
                        &ack_request,
                        "test historical shard ack inspection",
                    )
                    .unwrap()
                    .load()
                    .unwrap(),
                ack
            );
        });

        for result in [
            handler.retained_shard_inspection_route(
                &active_permit,
                &payload_request,
                "test historical shard inspection",
            ),
            handler.retained_shard_inspection_route(
                &foreign_permit,
                &payload_request,
                "test historical shard inspection",
            ),
        ] {
            match result {
                Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
                Ok(_) => panic!("invalid admission created historical shard authority"),
            }
        }
        for result in [
            handler.retained_shard_ack_inspection_route(
                &active_permit,
                &ack_request,
                "test historical shard ack inspection",
            ),
            handler.retained_shard_ack_inspection_route(
                &foreign_permit,
                &ack_request,
                "test historical shard ack inspection",
            ),
        ] {
            match result {
                Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
                Ok(_) => panic!("invalid admission created historical shard-ack authority"),
            }
        }
        let crossed_payload_request = StorageRpcShardReadRequest {
            location: test_location_with_shard(3, 0, config.node_id.as_u32(), 1).into(),
            ..payload_request.clone()
        };
        let crossed = match handler.retained_shard_inspection_route(
            &retained_permit,
            &crossed_payload_request,
            "test historical shard inspection",
        ) {
            Err(error) => error,
            Ok(_) => panic!("crossed shard subject created historical inspection authority"),
        };
        assert_eq!(crossed.code, StorageRpcErrorCode::PayloadDecode);

        let unretained_payload_request = StorageRpcShardReadRequest {
            location: test_location(2, 0, config.node_id.as_u32()).into(),
            ..payload_request.clone()
        };
        let unretained = match handler.retained_shard_inspection_route(
            &retained_permit,
            &unretained_payload_request,
            "test historical shard inspection",
        ) {
            Err(error) => error,
            Ok(_) => panic!("unretained route created historical shard authority"),
        };
        assert_eq!(unretained.code, StorageRpcErrorCode::StaleShardLocation);
        let unretained_ack_request = StorageRpcShardAckItemRequest {
            cluster_epoch: ClusterEpoch::new(2).unwrap(),
            ..ack_request.clone()
        };
        let unretained_ack = match handler.retained_shard_ack_inspection_route(
            &retained_permit,
            &unretained_ack_request,
            "test historical shard ack inspection",
        ) {
            Err(error) => error,
            Ok(_) => panic!("unretained route created historical shard-ack authority"),
        };
        assert_eq!(unretained_ack.code, StorageRpcErrorCode::StaleShardLocation);

        let wrong_primary_request = StorageRpcShardAckItemRequest {
            cluster_epoch: ClusterEpoch::new(1).unwrap(),
            ..ack_request.clone()
        };
        let wrong_primary = match handler.retained_shard_ack_inspection_route(
            &retained_permit,
            &wrong_primary_request,
            "test historical shard ack inspection",
        ) {
            Err(error) => error,
            Ok(_) => panic!("non-primary node created historical ack inspection authority"),
        };
        assert_eq!(wrong_primary.code, StorageRpcErrorCode::NonActingSetAccess);
    }

    #[test]
    fn active_data_capabilities_bind_admission_subject_and_captured_deadline() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.route_map_validity = RouteMapValidity::until_ms(5_000).unwrap();
        private_socket_dir(config.socket_path.parent().unwrap());
        let server = crate::clock::with_time_override(1_000, || {
            StorageNodeServer::bind(config.clone()).unwrap()
        });
        let handler = server.connection_handler();
        let active_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let retained_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let foreign_permit = StorageNodeRouteAdmissionGate::default()
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let shard_key = test_shard_key(0);
        let other_shard_key = test_shard_key(1);
        let location = test_location(1, 0, 7);
        let payload = b"active data capability payload";
        let repaired_payload = b"active data capability repaired payload";
        let repaired_ack = WriteAck {
            stored_size: repaired_payload.len() as u64,
            crc64: checksum::crc64::checksum(repaired_payload),
        };
        let ack_item = StorageRpcShardAckItem {
            shard_key: shard_key.clone(),
            ack: repaired_ack,
        };

        let shard_route = crate::clock::with_time_override(1_000, || {
            handler
                .active_shard_route(
                    &active_permit,
                    location.into(),
                    &shard_key,
                    "test active shard",
                )
                .unwrap()
        });
        let ack_route = crate::clock::with_time_override(1_000, || {
            handler
                .active_primary_data_route(
                    &active_permit,
                    config.node_id,
                    config.cluster_epoch,
                    PgId::new(0),
                    "test active shard ack",
                )
                .unwrap()
        });
        crate::clock::with_time_override(1_000, || {
            shard_route
                .write_if_absent(
                    payload,
                    AdmittedRouteEffectFence::unbounded(config.cluster_epoch),
                )
                .unwrap();
            assert_eq!(shard_route.read().unwrap(), payload);
            assert_eq!(
                shard_route.repair_write(repaired_payload).unwrap(),
                repaired_ack
            );
            assert_eq!(shard_route.read().unwrap(), repaired_payload);
            ack_route
                .record_shard_acks(std::slice::from_ref(&ack_item))
                .unwrap();
            ack_route
                .validate_shard_acks(std::slice::from_ref(&ack_item))
                .unwrap();
            assert_eq!(ack_route.load_shard_ack(&shard_key).unwrap(), repaired_ack);
        });

        crate::clock::with_time_override(1_000, || {
            for result in [
                handler.active_shard_route(
                    &retained_permit,
                    location.into(),
                    &shard_key,
                    "test active shard",
                ),
                handler.active_shard_route(
                    &foreign_permit,
                    location.into(),
                    &shard_key,
                    "test active shard",
                ),
            ] {
                match result {
                    Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
                    Ok(_) => panic!("invalid admission created an active shard capability"),
                }
            }
            let mismatched_location = test_location_with_shard(1, 0, 7, 1);
            let mismatch = match handler.active_shard_route(
                &active_permit,
                mismatched_location.into(),
                &shard_key,
                "test active shard",
            ) {
                Err(error) => error,
                Ok(_) => panic!("mismatched shard index created an active shard capability"),
            };
            assert_eq!(mismatch.code, StorageRpcErrorCode::PayloadDecode);

            for result in [
                handler.active_primary_data_route(
                    &retained_permit,
                    config.node_id,
                    config.cluster_epoch,
                    PgId::new(0),
                    "test active shard ack",
                ),
                handler.active_primary_data_route(
                    &foreign_permit,
                    config.node_id,
                    config.cluster_epoch,
                    PgId::new(0),
                    "test active shard ack",
                ),
            ] {
                match result {
                    Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
                    Ok(_) => {
                        panic!("invalid admission created an active data-primary capability")
                    }
                }
            }
        });

        let mut extended = config.clone();
        extended.route_map_validity = RouteMapValidity::until_ms(10_000).unwrap();
        crate::clock::with_time_override(1_000, || {
            server
                .install_control_plane_runtime_config(extended)
                .unwrap();
        });
        crate::clock::with_time_override(6_000, || {
            fn assert_expired<T>(result: Result<T, StorageNodeDataRouteError>) {
                match result {
                    Err(StorageNodeDataRouteError::Route(error)) => {
                        assert_eq!(error.code, StorageRpcErrorCode::StaleShardLocation);
                    }
                    Err(StorageNodeDataRouteError::Store(error)) => {
                        panic!("expired data capability reached node state: {error}")
                    }
                    Ok(_) => panic!("expired data capability reached node state"),
                }
            }

            assert_expired(shard_route.repair_write(b"must not replace"));
            assert_expired(shard_route.read());
            assert_expired(ack_route.record_shard_acks(&[StorageRpcShardAckItem {
                shard_key: other_shard_key.clone(),
                ack: repaired_ack,
            }]));
            assert_expired(ack_route.validate_shard_acks(std::slice::from_ref(&ack_item)));
            assert_expired(ack_route.load_shard_ack(&shard_key));
        });
        assert_eq!(
            server._node.read_shard_file(0, &shard_key).unwrap(),
            repaired_payload
        );
        assert!(matches!(
            server._node.get_pg(0).unwrap().stat_shard(&other_shard_key),
            Err(StoreError::NotFound)
        ));
    }

    #[test]
    fn read_handle_capabilities_bind_admission_subject_deadline_and_session() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.route_map_validity = RouteMapValidity::until_ms(5_000).unwrap();
        private_socket_dir(config.socket_path.parent().unwrap());
        let server = crate::clock::with_time_override(1_000, || {
            StorageNodeServer::bind(config.clone()).unwrap()
        });
        let handler = server.connection_handler();
        let active_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let retained_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let foreign_active_permit = StorageNodeRouteAdmissionGate::default()
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let foreign_retained_permit = StorageNodeRouteAdmissionGate::default()
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let mut session =
            StorageNodeSession::new(Arc::clone(&server.read_handles), Arc::clone(&server._node));
        let foreign_handles = Arc::new(Mutex::new(StorageNodeReadHandleState::default()));
        let mut foreign_session =
            StorageNodeSession::new(Arc::clone(&foreign_handles), Arc::clone(&server._node));
        let foreign_node =
            Arc::new(SharedStorageNode::topology_only(&[0], config.default_ec_shape).unwrap());
        let mut foreign_node_session =
            StorageNodeSession::new(Arc::clone(&server.read_handles), foreign_node);
        let first_location = test_location(1, 0, config.node_id.as_u32());
        let second_location = test_location_with_shard(1, 0, config.node_id.as_u32(), 1);
        let first_request = StorageRpcReadHandleAcquireRequest {
            read_operation_id: "capability-read-a".to_string(),
            locations: vec![first_location.into()],
            shard_keys: vec![test_shard_key(0)],
        };
        let second_request = StorageRpcReadHandleAcquireRequest {
            read_operation_id: "capability-read-b".to_string(),
            locations: vec![second_location.into()],
            shard_keys: vec![test_shard_key(1)],
        };

        crate::clock::with_time_override(1_000, || {
            for error in [
                match handler.active_read_handle_acquire_route(
                    &retained_permit,
                    &mut session,
                    &first_request,
                    "test read-handle acquire",
                ) {
                    Err(error) => error,
                    Ok(_) => panic!("retained admission created read-handle acquire authority"),
                },
                match handler.active_read_handle_acquire_route(
                    &foreign_active_permit,
                    &mut session,
                    &first_request,
                    "test read-handle acquire",
                ) {
                    Err(error) => error,
                    Ok(_) => panic!("foreign admission created read-handle acquire authority"),
                },
                match handler.active_read_handle_acquire_route(
                    &active_permit,
                    &mut foreign_session,
                    &first_request,
                    "test read-handle acquire",
                ) {
                    Err(error) => error,
                    Ok(_) => panic!("foreign registry created read-handle acquire authority"),
                },
                match handler.active_read_handle_acquire_route(
                    &active_permit,
                    &mut foreign_node_session,
                    &first_request,
                    "test read-handle acquire",
                ) {
                    Err(error) => error,
                    Ok(_) => panic!("foreign node created read-handle acquire authority"),
                },
            ] {
                assert_eq!(error.code, StorageRpcErrorCode::Internal);
            }
            let crossed_request = StorageRpcReadHandleAcquireRequest {
                shard_keys: vec![test_shard_key(1)],
                ..first_request.clone()
            };
            let crossed = match handler.active_read_handle_acquire_route(
                &active_permit,
                &mut session,
                &crossed_request,
                "test read-handle acquire",
            ) {
                Err(error) => error,
                Ok(_) => panic!("crossed shard subject created read-handle acquire authority"),
            };
            assert_eq!(crossed.code, StorageRpcErrorCode::PayloadDecode);
            let malformed_request = StorageRpcReadHandleAcquireRequest {
                read_operation_id: String::new(),
                ..first_request.clone()
            };
            let malformed = match handler.active_read_handle_acquire_route(
                &active_permit,
                &mut session,
                &malformed_request,
                "test read-handle acquire",
            ) {
                Err(error) => error,
                Ok(_) => panic!("malformed subject created read-handle acquire authority"),
            };
            assert_eq!(malformed.code, StorageRpcErrorCode::PayloadDecode);

            handler
                .active_read_handle_acquire_route(
                    &active_permit,
                    &mut session,
                    &first_request,
                    "test read-handle acquire",
                )
                .unwrap()
                .acquire()
                .unwrap();
            handler
                .active_read_handle_acquire_route(
                    &active_permit,
                    &mut session,
                    &second_request,
                    "test read-handle acquire",
                )
                .unwrap()
                .acquire()
                .unwrap();
        });
        assert_eq!(server.read_handle_count(first_location), 1);
        assert_eq!(server.read_handle_count(second_location), 1);

        let expiring_request = StorageRpcReadHandleAcquireRequest {
            read_operation_id: "capability-read-expired".to_string(),
            ..first_request.clone()
        };
        let expiring_route = crate::clock::with_time_override(1_000, || {
            handler
                .active_read_handle_acquire_route(
                    &active_permit,
                    &mut session,
                    &expiring_request,
                    "test read-handle acquire",
                )
                .unwrap()
        });
        let mut extended = config.clone();
        extended.route_map_validity = RouteMapValidity::until_ms(10_000).unwrap();
        crate::clock::with_time_override(1_000, || {
            server
                .install_control_plane_runtime_config(extended)
                .unwrap();
        });
        crate::clock::with_time_override(6_000, || {
            let error = expiring_route.acquire().unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::StaleShardLocation);
        });
        assert_eq!(server.read_handle_count(first_location), 1);

        let first_release = StorageRpcReadHandleReleaseRequest {
            read_operation_id: first_request.read_operation_id.clone(),
        };
        for error in [
            match handler.retained_read_handle_release_route(
                &active_permit,
                &mut session,
                &first_release,
                "test read-handle release",
            ) {
                Err(error) => error,
                Ok(_) => panic!("active admission created read-handle release authority"),
            },
            match handler.retained_read_handle_release_route(
                &foreign_retained_permit,
                &mut session,
                &first_release,
                "test read-handle release",
            ) {
                Err(error) => error,
                Ok(_) => panic!("foreign admission created read-handle release authority"),
            },
            match handler.retained_read_handle_release_route(
                &retained_permit,
                &mut foreign_session,
                &first_release,
                "test read-handle release",
            ) {
                Err(error) => error,
                Ok(_) => panic!("foreign registry created read-handle release authority"),
            },
            match handler.retained_read_handle_release_route(
                &retained_permit,
                &mut foreign_node_session,
                &first_release,
                "test read-handle release",
            ) {
                Err(error) => error,
                Ok(_) => panic!("foreign node created read-handle release authority"),
            },
        ] {
            assert_eq!(error.code, StorageRpcErrorCode::Internal);
        }
        let malformed_release = StorageRpcReadHandleReleaseRequest {
            read_operation_id: String::new(),
        };
        let malformed = match handler.retained_read_handle_release_route(
            &retained_permit,
            &mut session,
            &malformed_release,
            "test read-handle release",
        ) {
            Err(error) => error,
            Ok(_) => panic!("malformed subject created read-handle release authority"),
        };
        assert_eq!(malformed.code, StorageRpcErrorCode::PayloadDecode);
        crate::clock::with_time_override(6_000, || {
            handler
                .retained_read_handle_release_route(
                    &retained_permit,
                    &mut session,
                    &first_release,
                    "test read-handle release",
                )
                .unwrap()
                .release()
                .unwrap();
        });
        assert_eq!(server.read_handle_count(first_location), 0);
        assert_eq!(server.read_handle_count(second_location), 1);

        let second_release = StorageRpcReadHandleReleaseRequest {
            read_operation_id: second_request.read_operation_id,
        };
        handler
            .retained_read_handle_release_route(
                &retained_permit,
                &mut session,
                &second_release,
                "test read-handle release",
            )
            .unwrap()
            .release()
            .unwrap();
        assert_eq!(server.read_handle_count(second_location), 0);
        assert_eq!(foreign_handles.lock().unwrap().live_read_operations, 0);
    }

    #[test]
    fn object_payload_lease_capabilities_separate_active_and_retained_controls() {
        let tmp = test_util::tempdir();
        let config = test_config(&tmp);
        private_socket_dir(config.socket_path.parent().unwrap());
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let handler = server.connection_handler();
        let active_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let retained_permit = server
            .route_admission
            .acquire(StorageNodeRouteAdmissionClass::RetainedCleanup);
        let foreign_active = StorageNodeRouteAdmissionGate::default()
            .acquire(StorageNodeRouteAdmissionClass::Active);
        let bucket = BucketName::new("lease-capability").unwrap();
        let key = ObjectKey::new("source").unwrap();
        let generation_id = GenerationId::new(1).unwrap();
        let active_request = StorageRpcObjectPayloadLeaseControlRequest {
            node_id: config.node_id,
            route_cluster_epoch: config.cluster_epoch,
            bucket: bucket.clone(),
            key: key.clone(),
            generation_id,
            operation: StorageRpcObjectPayloadLeaseControlOperation::Acquire,
            reclaim_authority: None,
        };
        let retained_request = StorageRpcObjectPayloadLeaseControlRequest {
            operation: StorageRpcObjectPayloadLeaseControlOperation::Release,
            ..active_request.clone()
        };
        let reclaim_request = StorageRpcObjectPayloadLeaseControlRequest {
            operation: StorageRpcObjectPayloadLeaseControlOperation::ReclaimBegin,
            reclaim_authority: Some(crate::metadata_command::ObjectPayloadReclaimClaimProof {
                bucket_incarnation_generation: 1,
                reclaim_kind: crate::ObjectPayloadReclaimKind::ObjectSegments,
                claim_id: "claim".to_string(),
                owner_token: "owner".to_string(),
                cluster_epoch: config.cluster_epoch,
            }),
            ..active_request.clone()
        };

        handler
            .active_object_payload_lease_control(&active_permit, &active_request)
            .unwrap()
            .require_valid_now()
            .unwrap();
        handler
            .active_object_payload_lease_control(&active_permit, &reclaim_request)
            .unwrap()
            .require_valid_now()
            .unwrap();
        handler
            .retained_object_payload_lease_control(&retained_permit, &retained_request)
            .unwrap()
            .require_valid_now()
            .unwrap();

        for result in [
            handler.active_object_payload_lease_control(&retained_permit, &active_request),
            handler.active_object_payload_lease_control(&foreign_active, &active_request),
        ] {
            match result {
                Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
                Ok(_) => panic!("invalid admission created an active lease capability"),
            }
        }
        match handler.retained_object_payload_lease_control(&active_permit, &retained_request) {
            Err(error) => assert_eq!(error.code, StorageRpcErrorCode::Internal),
            Ok(_) => panic!("active admission created a retained lease capability"),
        }
        let missing_authority = StorageRpcObjectPayloadLeaseControlRequest {
            reclaim_authority: None,
            ..reclaim_request
        };
        match handler.active_object_payload_lease_control(&active_permit, &missing_authority) {
            Err(error) => assert_eq!(error.code, StorageRpcErrorCode::PayloadDecode),
            Ok(_) => panic!("reclaim begin without authority created a capability"),
        }
    }

    #[test]
    fn storage_node_server_retries_lost_shard_ack_record_exactly() {
        let tmp = test_util::tempdir();
        let config = test_config(&tmp);
        private_socket_dir(config.socket_path.parent().unwrap());
        let shard_key = test_shard_key(0);
        let ack = WriteAck {
            stored_size: 12,
            crc64: 0x1234,
        };
        let request = StorageRpcShardAckBatchRequest {
            node_id: NodeId::new(7),
            cluster_epoch: ClusterEpoch::new(1).unwrap(),
            pg_id: PgId::new(0),
            items: vec![StorageRpcShardAckItem {
                shard_key: shard_key.clone(),
                ack,
            }],
        };
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());

        let mut client = UnixStream::connect(socket_path).unwrap();
        for request_id in [1, 2] {
            let response = send_frame(
                &mut client,
                request_id,
                StorageRpcMessageKind::ShardAckRecord,
                encode_shard_ack_batch_request(&request).unwrap(),
            );
            decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap();
        }
        let validate = send_frame(
            &mut client,
            3,
            StorageRpcMessageKind::ShardAckValidate,
            encode_shard_ack_batch_request(&request).unwrap(),
        );
        decode_storage_rpc_response_payload(&validate.payload)
            .unwrap()
            .unwrap();

        let mismatch = StorageRpcShardAckBatchRequest {
            items: vec![StorageRpcShardAckItem {
                shard_key,
                ack: WriteAck {
                    stored_size: 13,
                    crc64: 0x1234,
                },
            }],
            ..request
        };
        let mismatch_response = send_frame(
            &mut client,
            4,
            StorageRpcMessageKind::ShardAckRecord,
            encode_shard_ack_batch_request(&mismatch).unwrap(),
        );
        drop(client);
        join.join().unwrap();

        let error = decode_storage_rpc_response_payload(&mismatch_response.payload)
            .unwrap()
            .unwrap_err();
        assert_eq!(error.code, StorageRpcErrorCode::ShardIntegrity);
        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        let pg = reopened.get_pg(0).unwrap();
        pg.validate_written_shard_ack(&mismatch.items[0].shard_key, ack)
            .unwrap();
    }

    #[test]
    fn storage_node_server_loads_and_retries_lost_shard_ack_delete() {
        let tmp = test_util::tempdir();
        let config = test_config(&tmp);
        private_socket_dir(config.socket_path.parent().unwrap());
        let shard_key = test_shard_key(0);
        let ack = WriteAck {
            stored_size: 12,
            crc64: 0x1234,
        };
        let record = StorageRpcShardAckBatchRequest {
            node_id: NodeId::new(7),
            cluster_epoch: ClusterEpoch::new(1).unwrap(),
            pg_id: PgId::new(0),
            items: vec![StorageRpcShardAckItem {
                shard_key: shard_key.clone(),
                ack,
            }],
        };
        let item = StorageRpcShardAckItemRequest {
            node_id: NodeId::new(7),
            cluster_epoch: ClusterEpoch::new(1).unwrap(),
            pg_id: PgId::new(0),
            shard_key: shard_key.clone(),
        };
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());

        let mut client = UnixStream::connect(socket_path).unwrap();
        let record_response = send_frame(
            &mut client,
            1,
            StorageRpcMessageKind::ShardAckRecord,
            encode_shard_ack_batch_request(&record).unwrap(),
        );
        decode_storage_rpc_response_payload(&record_response.payload)
            .unwrap()
            .unwrap();

        let load_response = send_frame(
            &mut client,
            2,
            StorageRpcMessageKind::ShardAckLoad,
            encode_shard_ack_item_request(&item),
        );
        let load_payload = decode_storage_rpc_response_payload(&load_response.payload)
            .unwrap()
            .unwrap();
        let loaded = decode_shard_ack_item_response(&load_payload).unwrap();
        assert_eq!(loaded.shard_key, shard_key);
        assert_eq!(loaded.ack, ack);

        for request_id in [3, 4] {
            let delete_response = send_frame(
                &mut client,
                request_id,
                StorageRpcMessageKind::ShardAckDelete,
                encode_shard_ack_item_request(&item),
            );
            decode_storage_rpc_response_payload(&delete_response.payload)
                .unwrap()
                .unwrap();
        }
        drop(client);
        join.join().unwrap();

        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        let pg = reopened.get_pg(0).unwrap();
        assert!(matches!(
            pg.stat_shard(&shard_key),
            Err(StoreError::NotFound)
        ));
    }

    #[test]
    fn storage_node_server_shard_ack_metadata_requires_pg_primary() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.node_id = NodeId::new(8);
        config.cluster_epoch = ClusterEpoch::new(2).unwrap();
        config.pg_routes[0].cluster_epoch = config.cluster_epoch;
        config.pg_routes[0].primary_node_id = NodeId::new(7);
        config.pg_routes[0].acting_set = vec![NodeId::new(7), NodeId::new(8)];
        config.historical_pg_routes = vec![StorageNodePgRoute {
            pg_id: 0,
            cluster_epoch: ClusterEpoch::new(1).unwrap(),
            state: PgState::Active,
            primary_node_id: NodeId::new(8),
            acting_set: vec![NodeId::new(7), NodeId::new(8)],
        }];
        private_socket_dir(config.socket_path.parent().unwrap());
        let existing_key = test_shard_key(0);
        let new_key = test_shard_key(1);
        let ack = WriteAck {
            stored_size: 12,
            crc64: 0x1234,
        };
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        {
            let pg = server._node.get_pg(0).unwrap();
            pg.register_written_shards_batch_exact(&[(&existing_key, ack)])
                .unwrap();
        }
        let record = StorageRpcShardAckBatchRequest {
            node_id: NodeId::new(8),
            cluster_epoch: config.cluster_epoch,
            pg_id: PgId::new(0),
            items: vec![StorageRpcShardAckItem {
                shard_key: new_key.clone(),
                ack,
            }],
        };
        let existing_record = StorageRpcShardAckBatchRequest {
            items: vec![StorageRpcShardAckItem {
                shard_key: existing_key.clone(),
                ack,
            }],
            ..record.clone()
        };
        let existing_item = StorageRpcShardAckItemRequest {
            node_id: NodeId::new(8),
            cluster_epoch: config.cluster_epoch,
            pg_id: PgId::new(0),
            shard_key: existing_key.clone(),
        };
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());

        let mut client = UnixStream::connect(socket_path).unwrap();
        let requests = [
            (
                StorageRpcMessageKind::ShardAckRecord,
                encode_shard_ack_batch_request(&record).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardAckValidate,
                encode_shard_ack_batch_request(&existing_record).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardAckLoad,
                encode_shard_ack_item_request(&existing_item),
            ),
            (
                StorageRpcMessageKind::ShardAckDelete,
                encode_shard_ack_item_request(&existing_item),
            ),
        ];
        for (index, (kind, payload)) in requests.into_iter().enumerate() {
            let response = send_frame(&mut client, index as u64 + 1, kind, payload);
            let error = decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::NonActingSetAccess);
        }
        let historical_load = send_frame(
            &mut client,
            5,
            StorageRpcMessageKind::ShardAckHistoricalLoad,
            encode_shard_ack_item_request(&StorageRpcShardAckItemRequest {
                cluster_epoch: ClusterEpoch::new(1).unwrap(),
                ..existing_item.clone()
            }),
        );
        let historical_payload = decode_storage_rpc_response_payload(&historical_load.payload)
            .unwrap()
            .unwrap();
        let historical_item = decode_shard_ack_item_response(&historical_payload).unwrap();
        assert_eq!(historical_item.shard_key, existing_key);
        assert_eq!(historical_item.ack, ack);
        drop(client);
        join.join().unwrap();

        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        let pg = reopened.get_pg(0).unwrap();
        pg.validate_written_shard_ack(&existing_key, ack).unwrap();
        assert!(matches!(pg.stat_shard(&new_key), Err(StoreError::NotFound)));
    }

    #[test]
    fn storage_node_server_rejects_unknown_data_pg_for_every_shard_ack_operation() {
        let tmp = test_util::tempdir();
        let config = test_config(&tmp);
        private_socket_dir(config.socket_path.parent().unwrap());
        let record_key = test_shard_key(0);
        let canary_key = test_shard_key(1);
        let record_ack = WriteAck {
            stored_size: 12,
            crc64: 0x1234,
        };
        let canary_ack = WriteAck {
            stored_size: 34,
            crc64: 0x5678,
        };
        let batch = StorageRpcShardAckBatchRequest {
            node_id: config.node_id,
            cluster_epoch: config.cluster_epoch,
            pg_id: PgId::new(9),
            items: vec![StorageRpcShardAckItem {
                shard_key: record_key.clone(),
                ack: record_ack,
            }],
        };
        let unknown_record_item = StorageRpcShardAckItemRequest {
            node_id: config.node_id,
            cluster_epoch: config.cluster_epoch,
            pg_id: PgId::new(9),
            shard_key: record_key.clone(),
        };
        let unknown_canary_item = StorageRpcShardAckItemRequest {
            shard_key: canary_key.clone(),
            ..unknown_record_item.clone()
        };
        let configured_record_item = StorageRpcShardAckItemRequest {
            pg_id: PgId::new(0),
            ..unknown_record_item.clone()
        };
        let configured_canary_item = StorageRpcShardAckItemRequest {
            pg_id: PgId::new(0),
            shard_key: canary_key.clone(),
            ..unknown_record_item.clone()
        };
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        server
            ._node
            .get_pg(0)
            .unwrap()
            .register_written_shards_batch_exact(&[(&canary_key, canary_ack)])
            .unwrap();
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());

        let mut client = UnixStream::connect(socket_path).unwrap();
        let record_response = send_frame(
            &mut client,
            1,
            StorageRpcMessageKind::ShardAckRecord,
            encode_shard_ack_batch_request(&batch).unwrap(),
        );
        let record_error = decode_storage_rpc_response_payload(&record_response.payload)
            .unwrap()
            .unwrap_err();
        assert_eq!(record_error.code, StorageRpcErrorCode::UnknownPg);

        let absent_response = send_frame(
            &mut client,
            2,
            StorageRpcMessageKind::ShardAckLoad,
            encode_shard_ack_item_request(&configured_record_item),
        );
        let absent_error = decode_storage_rpc_response_payload(&absent_response.payload)
            .unwrap()
            .unwrap_err();
        assert_eq!(absent_error.code, StorageRpcErrorCode::NotFound);

        let canary_after_record = send_frame(
            &mut client,
            3,
            StorageRpcMessageKind::ShardAckLoad,
            encode_shard_ack_item_request(&configured_canary_item),
        );
        let canary_after_record = decode_storage_rpc_response_payload(&canary_after_record.payload)
            .unwrap()
            .unwrap();
        assert_eq!(
            decode_shard_ack_item_response(&canary_after_record).unwrap(),
            StorageRpcShardAckItem {
                shard_key: canary_key.clone(),
                ack: canary_ack,
            }
        );

        let read_only_requests = [
            (
                StorageRpcMessageKind::ShardAckValidate,
                encode_shard_ack_batch_request(&batch).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardAckLoad,
                encode_shard_ack_item_request(&unknown_record_item),
            ),
            (
                StorageRpcMessageKind::ShardAckHistoricalLoad,
                encode_shard_ack_item_request(&unknown_record_item),
            ),
        ];
        for (index, (kind, payload)) in read_only_requests.into_iter().enumerate() {
            let response = send_frame(&mut client, index as u64 + 4, kind, payload);
            let error = decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::UnknownPg);
        }

        let delete_response = send_frame(
            &mut client,
            7,
            StorageRpcMessageKind::ShardAckDelete,
            encode_shard_ack_item_request(&unknown_canary_item),
        );
        let delete_error = decode_storage_rpc_response_payload(&delete_response.payload)
            .unwrap()
            .unwrap_err();
        assert_eq!(delete_error.code, StorageRpcErrorCode::UnknownPg);

        let canary_after_delete = send_frame(
            &mut client,
            8,
            StorageRpcMessageKind::ShardAckLoad,
            encode_shard_ack_item_request(&configured_canary_item),
        );
        let canary_after_delete = decode_storage_rpc_response_payload(&canary_after_delete.payload)
            .unwrap()
            .unwrap();
        assert_eq!(
            decode_shard_ack_item_response(&canary_after_delete).unwrap(),
            StorageRpcShardAckItem {
                shard_key: canary_key.clone(),
                ack: canary_ack,
            }
        );
        drop(client);
        join.join().unwrap();

        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        let pg = reopened.get_pg(0).unwrap();
        assert!(matches!(
            pg.stat_shard(&record_key),
            Err(StoreError::NotFound)
        ));
        pg.validate_written_shard_ack(&canary_key, canary_ack)
            .unwrap();
    }

    #[test]
    fn storage_node_server_repair_and_backfill_rpcs_validate_data_pg_before_rows() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.pg_ids = vec![0, 1];
        config.pg_routes = vec![test_route(0), test_route(1)];
        private_socket_dir(config.socket_path.parent().unwrap());
        let route = StorageRpcBucketPgRequest {
            node_id: config.node_id,
            cluster_epoch: config.cluster_epoch,
            pg_id: PgId::new(1),
        };
        let unknown_route = StorageRpcBucketPgRequest {
            pg_id: PgId::new(9),
            ..route.clone()
        };
        let request = SegmentStoredBytesRequest {
            data_pg_id: 0,
            segment_okh: [0xAC; 16],
            segment_vid: GenerationId::new(42).unwrap(),
            stored_size: 1024,
            segment_crc64: 0x1234,
            ec: EcShape { k: 4, m: 2 },
        };
        let repair_work_item = PlacedSegmentShardRepairWorkItem {
            request,
            shard_index: ShardIndex::new(5),
        };
        let backfill_work_item = PlacedSegmentShardBackfillWorkItem {
            request,
            source_cluster_epoch: ClusterEpoch::new(1).unwrap(),
            desired_cluster_epoch: ClusterEpoch::new(2).unwrap(),
        };
        let repair_acquire = PlacedSegmentShardRepairClaimAcquire {
            claim_id: "repair-canary-claim".to_string(),
            owner_token: "repair-canary-owner".to_string(),
            cluster_epoch: config.cluster_epoch,
            claimed_at: 10,
            lease_deadline: 20,
            now: 10,
        };
        let backfill_acquire = PlacedSegmentShardBackfillClaimAcquire {
            claim_id: "backfill-canary-claim".to_string(),
            owner_token: "backfill-canary-owner".to_string(),
            cluster_epoch: config.cluster_epoch,
            claimed_at: 10,
            lease_deadline: 20,
            now: 10,
        };
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let (
            repair_records_before,
            repair_claim_before,
            backfill_records_before,
            backfill_claim_before,
        ) = {
            let pg = server._node.get_pg(0).unwrap();
            pg.record_placed_segment_shard_repair(&repair_work_item, None)
                .unwrap();
            let repair_claim = pg
                .acquire_placed_segment_shard_repair_claim(&repair_acquire)
                .unwrap()
                .unwrap();
            pg.record_placed_segment_shard_backfill(
                &backfill_work_item,
                backfill_work_item.request.ec.m,
                None,
            )
            .unwrap();
            let backfill_claim = pg
                .acquire_placed_segment_shard_backfill_claim(&backfill_acquire)
                .unwrap()
                .unwrap();
            (
                pg.list_placed_segment_shard_repairs().unwrap(),
                repair_claim,
                pg.list_placed_segment_shard_backfills().unwrap(),
                backfill_claim,
            )
        };
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());
        let mut client = UnixStream::connect(socket_path).unwrap();

        let mismatched_requests = [
            (
                StorageRpcMessageKind::PlacedSegmentShardRepairRecord,
                encode_placed_segment_shard_repair_record_request(
                    &StorageRpcPlacedSegmentShardRepairRecordRequest {
                        route: route.clone(),
                        work_item: repair_work_item,
                        last_error: None,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardRepairResolve,
                encode_placed_segment_shard_repair_item_request(
                    &StorageRpcPlacedSegmentShardRepairItemRequest {
                        route: route.clone(),
                        work_item: repair_work_item,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardRepairClaimComplete,
                encode_placed_segment_shard_repair_claim_record_request(
                    &StorageRpcPlacedSegmentShardRepairClaimRecordRequest {
                        route: route.clone(),
                        claim: repair_claim_before.clone(),
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardRepairClaimError,
                encode_placed_segment_shard_repair_claim_error_request(
                    &StorageRpcPlacedSegmentShardRepairClaimErrorRequest {
                        route: route.clone(),
                        claim: repair_claim_before.clone(),
                        last_error: "must not persist".to_string(),
                        next_attempt_after: 30,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfillRecord,
                encode_placed_segment_shard_backfill_record_request(
                    &StorageRpcPlacedSegmentShardBackfillRecordRequest {
                        route: route.clone(),
                        work_item: backfill_work_item,
                        remaining_tolerance: backfill_work_item.request.ec.m,
                        last_error: None,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfillExists,
                encode_placed_segment_shard_backfill_item_request(
                    &StorageRpcPlacedSegmentShardBackfillItemRequest {
                        route: route.clone(),
                        work_item: backfill_work_item,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfillResolve,
                encode_placed_segment_shard_backfill_item_request(
                    &StorageRpcPlacedSegmentShardBackfillItemRequest {
                        route: route.clone(),
                        work_item: backfill_work_item,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfillClaimComplete,
                encode_placed_segment_shard_backfill_claim_record_request(
                    &StorageRpcPlacedSegmentShardBackfillClaimRecordRequest {
                        route: route.clone(),
                        claim: backfill_claim_before.clone(),
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfillClaimError,
                encode_placed_segment_shard_backfill_claim_error_request(
                    &StorageRpcPlacedSegmentShardBackfillClaimErrorRequest {
                        route,
                        claim: backfill_claim_before.clone(),
                        last_error: "must not persist".to_string(),
                        next_attempt_after: 30,
                    },
                )
                .unwrap(),
            ),
        ];
        let mut request_id = 1u64;
        for (kind, payload) in mismatched_requests {
            let response = send_frame(&mut client, request_id, kind, payload);
            request_id += 1;
            let error = decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::PayloadDecode);
        }

        let unknown_requests = [
            (
                StorageRpcMessageKind::PlacedSegmentShardRepairs,
                encode_bucket_pg_request(&unknown_route).unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardRepairClaimAcquire,
                encode_placed_segment_shard_repair_claim_acquire_request(
                    &StorageRpcPlacedSegmentShardRepairClaimAcquireRequest {
                        route: unknown_route.clone(),
                        claim_id: "unknown-repair-claim".to_string(),
                        owner_token: "unknown-repair-owner".to_string(),
                        claimed_at: 10,
                        lease_deadline: Some(20),
                        now: 10,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfills,
                encode_bucket_pg_request(&unknown_route).unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfillCount,
                encode_bucket_pg_request(&unknown_route).unwrap(),
            ),
            (
                StorageRpcMessageKind::PlacedSegmentShardBackfillClaimAcquire,
                encode_placed_segment_shard_backfill_claim_acquire_request(
                    &StorageRpcPlacedSegmentShardBackfillClaimAcquireRequest {
                        route: unknown_route,
                        claim_id: "unknown-backfill-claim".to_string(),
                        owner_token: "unknown-backfill-owner".to_string(),
                        claimed_at: 10,
                        lease_deadline: Some(20),
                        now: 10,
                    },
                )
                .unwrap(),
            ),
        ];
        for (kind, payload) in unknown_requests {
            let response = send_frame(&mut client, request_id, kind, payload);
            request_id += 1;
            let error = decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::UnknownPg);
        }
        drop(client);
        join.join().unwrap();

        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        let pg0 = reopened.get_pg(0).unwrap();
        let repairs = pg0.list_placed_segment_shard_repairs().unwrap();
        assert_eq!(repairs, repair_records_before);
        let repair_claim_after = pg0
            .acquire_placed_segment_shard_repair_claim(&repair_acquire)
            .unwrap()
            .unwrap();
        assert_eq!(repair_claim_after, repair_claim_before);
        let backfills = pg0.list_placed_segment_shard_backfills().unwrap();
        assert_eq!(backfills, backfill_records_before);
        let backfill_claim_after = pg0
            .acquire_placed_segment_shard_backfill_claim(&backfill_acquire)
            .unwrap()
            .unwrap();
        assert_eq!(backfill_claim_after, backfill_claim_before);
        let pg1 = reopened.get_pg(1).unwrap();
        assert!(pg1.list_placed_segment_shard_repairs().unwrap().is_empty());
        assert!(pg1
            .list_placed_segment_shard_backfills()
            .unwrap()
            .is_empty());
    }

    #[test]
    fn storage_node_server_shard_scavenger_rpcs_validate_roles_before_rows() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.pg_ids = vec![0, 1];
        config.pg_routes = vec![test_route(0), test_route(1)];
        private_socket_dir(config.socket_path.parent().unwrap());
        let pg0_key = test_shard_key(0);
        let pg0_observation = ShardScavengerObservationRecord {
            key: ShardScavengerObservationKey {
                node_id: config.node_id.as_u32(),
                data_pg_id: 0,
                shard_index: pg0_key.shard_index(),
                shard_key: pg0_key,
            },
            data_size: Some(12),
            crc64: Some(0x1234),
            file_exists: true,
            shard_row_exists: true,
            reason: ShardScavengerObservationReason::UnreferencedShardRowAndFile,
            last_error: None,
        };
        let pg1_key = test_shard_key(1);
        let pg1_observation = ShardScavengerObservationRecord {
            key: ShardScavengerObservationKey {
                node_id: config.node_id.as_u32(),
                data_pg_id: 1,
                shard_index: pg1_key.shard_index(),
                shard_key: pg1_key,
            },
            data_size: None,
            crc64: None,
            file_exists: false,
            shard_row_exists: false,
            reason: ShardScavengerObservationReason::ScanIncomplete,
            last_error: Some("pg 1 canary".to_string()),
        };
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let (pg0_before, pg1_before) = {
            let pg0 = server._node.get_pg(0).unwrap();
            pg0.record_shard_scavenger_observation(&pg0_observation)
                .unwrap();
            let pg0_before = pg0.list_shard_scavenger_observations().unwrap();
            let pg1 = server._node.get_pg(1).unwrap();
            pg1.record_shard_scavenger_observation(&pg1_observation)
                .unwrap();
            let pg1_before = pg1.list_shard_scavenger_observations().unwrap();
            (pg0_before, pg1_before)
        };
        let pg1_route = StorageRpcBucketPgRequest {
            node_id: config.node_id,
            cluster_epoch: config.cluster_epoch,
            pg_id: PgId::new(1),
        };
        let mut changed_pg0_observation = pg0_observation.clone();
        changed_pg0_observation.last_error = Some("must not persist".to_string());
        let unknown_route = StorageRpcBucketPgRequest {
            pg_id: PgId::new(9),
            ..pg1_route.clone()
        };
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());
        let mut client = UnixStream::connect(socket_path).unwrap();

        let mismatched_requests = [
            (
                StorageRpcMessageKind::ShardScavengerObservationRecord,
                encode_scavenger_observation_record_request(
                    &StorageRpcScavengerObservationRecordRequest {
                        route: pg1_route.clone(),
                        observation: changed_pg0_observation,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardScavengerObservationResolve,
                encode_scavenger_observation_key_request(
                    &StorageRpcScavengerObservationKeyRequest {
                        route: pg1_route,
                        key: pg0_observation.key.clone(),
                    },
                )
                .unwrap(),
            ),
        ];
        let mut request_id = 1u64;
        for (kind, payload) in mismatched_requests {
            let response = send_frame(&mut client, request_id, kind, payload);
            request_id += 1;
            let error = decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::PayloadDecode);
        }

        let unknown_requests = [
            (
                StorageRpcMessageKind::ShardScavengerListFiles,
                encode_scavenger_list_files_request(&StorageRpcScavengerListFilesRequest {
                    node_id: config.node_id,
                    cluster_epoch: config.cluster_epoch,
                    data_pg_id: PgId::new(9),
                }),
            ),
            (
                StorageRpcMessageKind::ShardScavengerShardRows,
                encode_bucket_pg_request(&unknown_route).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardScavengerPayloadReferences,
                encode_bucket_pg_request(&unknown_route).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardScavengerObservations,
                encode_bucket_pg_request(&unknown_route).unwrap(),
            ),
        ];
        for (kind, payload) in unknown_requests {
            let response = send_frame(&mut client, request_id, kind, payload);
            request_id += 1;
            let error = decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::UnknownPg);
        }
        drop(client);
        join.join().unwrap();

        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        assert_eq!(
            reopened
                .get_pg(0)
                .unwrap()
                .list_shard_scavenger_observations()
                .unwrap(),
            pg0_before
        );
        assert_eq!(
            reopened
                .get_pg(1)
                .unwrap()
                .list_shard_scavenger_observations()
                .unwrap(),
            pg1_before
        );
    }

    #[test]
    fn storage_node_server_shard_scavenger_metadata_requires_pg_primary() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.node_id = NodeId::new(8);
        config.pg_routes[0].primary_node_id = NodeId::new(7);
        config.pg_routes[0].acting_set = vec![NodeId::new(7), NodeId::new(8)];
        private_socket_dir(config.socket_path.parent().unwrap());
        let shard_key = test_shard_key(0);
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let route = StorageRpcBucketPgRequest {
            node_id: NodeId::new(8),
            cluster_epoch: ClusterEpoch::new(1).unwrap(),
            pg_id: PgId::new(0),
        };
        let observation_key = ShardScavengerObservationKey {
            node_id: 8,
            data_pg_id: 0,
            shard_index: shard_key.shard_index(),
            shard_key,
        };
        let observation = ShardScavengerObservationRecord {
            key: observation_key.clone(),
            data_size: Some(12),
            crc64: Some(0x1234),
            file_exists: true,
            shard_row_exists: true,
            reason: ShardScavengerObservationReason::UnreferencedShardRowAndFile,
            last_error: None,
        };
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());

        let mut client = UnixStream::connect(socket_path).unwrap();
        let requests = [
            (
                StorageRpcMessageKind::ShardScavengerShardRows,
                encode_bucket_pg_request(&route).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardScavengerPayloadReferences,
                encode_bucket_pg_request(&route).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardScavengerObservationRecord,
                encode_scavenger_observation_record_request(
                    &StorageRpcScavengerObservationRecordRequest {
                        route: route.clone(),
                        observation,
                    },
                )
                .unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardScavengerObservations,
                encode_bucket_pg_request(&route).unwrap(),
            ),
            (
                StorageRpcMessageKind::ShardScavengerObservationResolve,
                encode_scavenger_observation_key_request(
                    &StorageRpcScavengerObservationKeyRequest {
                        route,
                        key: observation_key,
                    },
                )
                .unwrap(),
            ),
        ];
        for (index, (kind, payload)) in requests.into_iter().enumerate() {
            let response = send_frame(&mut client, index as u64 + 1, kind, payload);
            let error = decode_storage_rpc_response_payload(&response.payload)
                .unwrap()
                .unwrap_err();
            assert_eq!(error.code, StorageRpcErrorCode::NonActingSetAccess);
        }
        drop(client);
        join.join().unwrap();

        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        let pg = reopened.get_pg(0).unwrap();
        assert!(pg.list_shard_scavenger_observations().unwrap().is_empty());
    }

    #[test]
    fn storage_node_server_rejects_stale_shard_ack_validate_before_rows() {
        let tmp = test_util::tempdir();
        let mut config = test_config(&tmp);
        config.cluster_epoch = ClusterEpoch::new(2).unwrap();
        config.pg_routes[0].cluster_epoch = ClusterEpoch::new(2).unwrap();
        private_socket_dir(config.socket_path.parent().unwrap());
        let shard_key = test_shard_key(0);
        let ack = WriteAck {
            stored_size: 12,
            crc64: 0x1234,
        };
        let server = StorageNodeServer::bind(config.clone()).unwrap();
        let pg = server._node.get_pg(0).unwrap();
        pg.register_written_shards_batch_exact(&[(&shard_key, ack)])
            .unwrap();
        drop(pg);
        let stale_request = StorageRpcShardAckBatchRequest {
            node_id: NodeId::new(7),
            cluster_epoch: ClusterEpoch::new(1).unwrap(),
            pg_id: PgId::new(0),
            items: vec![StorageRpcShardAckItem {
                shard_key: shard_key.clone(),
                ack,
            }],
        };
        let socket_path = config.socket_path.clone();
        let join = thread::spawn(move || server.accept_one().unwrap());

        let mut client = UnixStream::connect(socket_path).unwrap();
        let response = send_frame(
            &mut client,
            1,
            StorageRpcMessageKind::ShardAckValidate,
            encode_shard_ack_batch_request(&stale_request).unwrap(),
        );
        drop(client);
        join.join().unwrap();

        let error = decode_storage_rpc_response_payload(&response.payload)
            .unwrap()
            .unwrap_err();
        assert_eq!(error.code, StorageRpcErrorCode::StaleShardLocation);
        let reopened = SharedStorageNode::open_with_default_ec_shape(
            &config.data_dir,
            &config.pg_ids,
            config.default_ec_shape,
        )
        .unwrap();
        let pg = reopened.get_pg(0).unwrap();
        pg.validate_written_shard_ack(&shard_key, ack).unwrap();
    }

